import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  root.userData.handlers = {};

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const gradientT = smoothstep(0.05, 0.95, uv().y);
  backdropMaterial.colorNode = mix(
    color('#0b0b10'),
    mix(color('#16161d'), color('#0b0b10'), gradientT),
    smoothstep(0.08, 0.92, uv().x)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const panelGeometry = new PlaneGeometry(5.65, 3.85);
  const panelMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.94
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.set(0, 0, -1.8);
  panel.renderOrder = -5;
  root.add(panel);
  resources.push(panelGeometry, panelMaterial);

  const accentGeometry = new PlaneGeometry(0.055, 1.35);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.9
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(2.55, -0.72, -1.15);
  accent.renderOrder = 1;
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const paperGeometry = new PlaneGeometry(0.42, 0.025);
  const paperMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.72
  });
  const paperMark = new Mesh(paperGeometry, paperMaterial);
  paperMark.position.set(-2.55, 1.35, -1.12);
  paperMark.renderOrder = 1;
  root.add(paperMark);
  resources.push(paperGeometry, paperMaterial);

  const spriteGeometry = new PlaneGeometry(4.8, 3.0);
  const spriteMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1,
    depthWrite: false
  });
  const sprite = new Mesh(spriteGeometry, spriteMaterial);
  sprite.position.set(0, 0.08, -0.55);
  sprite.renderOrder = 5;

  sprite.onBeforeRender = (_renderer, _scene, camera) => {
    if (!disposed && camera) sprite.quaternion.copy(camera.quaternion);
  };

  root.add(sprite);
  resources.push(spriteGeometry, spriteMaterial);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (disposed) {
        loadedTexture.dispose?.();
        return;
      }

      const image = loadedTexture.image;
      const imageWidth = image?.width || 512;
      const imageHeight = image?.height || 320;
      const region = config.atlasRegion ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      loadedTexture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.wrapT = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.offset.set(
        region.x / imageWidth,
        1 - (region.y + region.height) / imageHeight
      );
      loadedTexture.repeat.set(
        region.width / imageWidth,
        region.height / imageHeight
      );
      if ('colorSpace' in loadedTexture && ctx.THREE.SRGBColorSpace) {
        loadedTexture.colorSpace = ctx.THREE.SRGBColorSpace;
      }
      loadedTexture.needsUpdate = true;

      spriteMaterial.map = loadedTexture;
      spriteMaterial.colorNode = texture(loadedTexture, uv());
      spriteMaterial.needsUpdate = true;
      resources.push(loadedTexture);
    }).catch(() => {});
  }

  const primitives = config.cinematicPrimitives ?? [];
  const primitiveResults = [];
  for (const primitive of primitives) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.traverse((object) => {
      object.onBeforeRender = null;
    });
  };

  return root;
}
